e = 0x10001

phi_n = (p - 1) * (q - 1)

d = inverse(e, phi_n)

flag_int = pow(ct, d, n)
flag = long_to_bytes(flag_int)
flag = flag[:-50]
print(flag.decode('latin-1'))



